pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address admin = address(this);
        vm.prank(admin);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(ok == true && c.owner() == newOwner);
    }
}
